import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/accessory/configuration.md","filePath":"en/modules/accessory/configuration.md","lastUpdated":0}`),a={name:`en/modules/accessory/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p><code>plugins/EmakiAccessory/config.yml</code> is the main configuration, and <code>pages/*.yml</code> defines the accessory pages. <code>version</code> is a configuration-structure marker maintained by the project resource sync flow; the plugin merges newly added default keys based on it.</p><h2 id="top-level-keys" tabindex="-1">Top-Level Keys <a class="header-anchor" href="#top-level-keys" aria-label="Permalink to “Top-Level Keys”">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>version</code></td><td><code>&quot;1.0.3&quot;</code></td><td>Configuration structure version, used to merge new default keys.</td></tr><tr><td><code>language</code></td><td><code>&quot;zh_CN&quot;</code></td><td>Language file name, resolving to <code>lang/&lt;language&gt;.yml</code>.</td></tr><tr><td><code>release_default_data</code></td><td><code>true</code></td><td>Whether the bundled default data files (<code>parts.yml</code> plus the examples under <code>pages/</code> and <code>sets/</code>) are released on every startup. While true, each startup restores missing default examples without overwriting existing files; once false, only existing data is kept and missing examples are no longer generated.</td></tr><tr><td><code>drop_on_death</code></td><td><code>false</code></td><td>Whether accessories drop on death.</td></tr><tr><td><code>unique</code></td><td><code>true</code></td><td>Whether wearing two identical accessories at once is forbidden.</td></tr><tr><td><code>slot_sources</code></td><td>see below</td><td>Additional sources declaring which slots an accessory may occupy.</td></tr><tr><td><code>persistence</code></td><td>see below</td><td>Autosave and shutdown flush parameters.</td></tr></tbody></table><h2 id="drop-on-death" tabindex="-1"><code>drop_on_death</code> <a class="header-anchor" href="#drop-on-death" aria-label="Permalink to “drop_on_death”">​</a></h2><p>When true, accessories are <strong>appended to the death drop list</strong> and handled by the vanilla death flow rather than being pushed back into the inventory — the latter would leave the same accessory in both the drops and the inventory.</p><p>The option has no effect when another plugin already enabled <code>keepInventory</code>; accessories are kept either way.</p><h2 id="unique" tabindex="-1"><code>unique</code> <a class="header-anchor" href="#unique" aria-label="Permalink to “unique”">​</a></h2><p>The preferred criterion is <strong>EmakiItem&#39;s item definition id</strong>, not the material: two accessories of the same definition count as duplicates even when their levels or affixes differ. When EmakiItem is unavailable, the check falls back to vanilla material comparison, so two accessories sharing a material are treated as duplicates.</p><h2 id="slot-sources" tabindex="-1"><code>slot_sources</code> <a class="header-anchor" href="#slot-sources" aria-label="Permalink to “slot_sources”">​</a></h2><p>Additional sources for the slots an accessory declares it can occupy. EmakiAttribute&#39;s <code>active_slot</code> and the EmakiSkills skill payload are <strong>always</strong> in effect; the two options below are appended on top. All four sources form a union: any match allows the accessory to be worn. With both options disabled, behavior matches a single-source setup.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>slot_sources.pdc.enabled</code></td><td><code>false</code></td><td>Whether to read a slot list from the item&#39;s PDC.</td></tr><tr><td><code>slot_sources.pdc.key</code></td><td><code>&quot;&quot;</code></td><td>Full NamespacedKey, used verbatim without case rewriting. A string list is preferred; when absent, a single string is read and split by <code>separator</code>.</td></tr><tr><td><code>slot_sources.lore.enabled</code></td><td><code>false</code></td><td>Whether to read a slot list from lore using regular expressions.</td></tr><tr><td><code>slot_sources.lore.patterns</code></td><td>see defaults</td><td>Regex list; capture group 1 of each pattern holds the slot list text. MiniMessage tags are stripped and whitespace collapsed before matching, so write plain-text patterns. An invalid pattern logs a warning and is skipped.</td></tr><tr><td><code>slot_sources.lore.separator</code></td><td><code>&quot;,&quot;</code></td><td>Slot list separator, also used by the <code>pdc</code> string fallback.</td></tr><tr><td><code>slot_sources.lore.aliases</code></td><td>see defaults</td><td>Maps display names in lore to part ids in <code>parts.yml</code>. Part ids allow only lowercase letters, digits, and underscores, so localized slot names must be mapped here; unlisted values are normalized as-is.</td></tr></tbody></table><h2 id="accessory-pages-pages-yml" tabindex="-1">Accessory pages: <code>pages/*.yml</code> <a class="header-anchor" href="#accessory-pages-pages-yml" aria-label="Permalink to “Accessory pages: pages/*.yml”">​</a></h2><p>Each file defines one page. The page id comes from <code>page_id</code>, independent of the file name.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">page_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;main&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">display_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gold&gt;Main Accessories&lt;/gold&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">order</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">gui_template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;accessory_gui&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">parts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;necklace&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ring&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;belt&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;charm&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>Description</th></tr></thead><tbody><tr><td><code>page_id</code></td><td>Page id, also the storage partition key inside player data.</td></tr><tr><td><code>display_name</code></td><td>Page display name with MiniMessage support, used by switch cells and <code>/eacc pages</code>.</td></tr><tr><td><code>order</code></td><td>Page sort order, ascending; the <strong>lowest value is the default enabled page</strong>.</td></tr><tr><td><code>gui_template</code></td><td>Layout id used by this page; several pages may share one layout.</td></tr><tr><td><code>permission</code></td><td>Empty means available to everyone; a non-empty value is matched verbatim.</td></tr><tr><td><code>parts</code></td><td>Parts enabled on this page; every value must be a part id defined in <code>parts.yml</code>.</td></tr></tbody></table><p>Three page rules:</p><ul><li><strong>Isolated storage:</strong> the same slot instance id holds a separate accessory on each page, with no overwriting.</li><li><strong>Only the enabled page contributes:</strong> accessories on other pages are kept but produce no attributes, skills, or set piece counts.</li><li><strong>Losing permission keeps data:</strong> when a player loses the enabled page&#39;s permission, nothing is cleared and no page switch happens. The page cannot be opened and its accessories stop contributing, and the player recovers items with <code>/eacc retrieve &lt;page&gt;</code>.</li></ul><p>Parts listed on a page expand into slot instances according to <code>count</code> in <code>parts.yml</code>, and each instance must be placed in the layout referenced by <code>gui_template</code>; otherwise the slot is unusable and a warning is logged.</p><h2 id="persistence" tabindex="-1"><code>persistence</code> <a class="header-anchor" href="#persistence" aria-label="Permalink to “persistence”">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>autosave_seconds</code></td><td><code>60</code></td><td>Autosave interval in seconds. Set to 0 or a negative value to disable timed saving.</td></tr><tr><td><code>drain_timeout_seconds</code></td><td><code>10</code></td><td>How many seconds to wait for unflushed writes during shutdown.</td></tr></tbody></table><p>With timed saving disabled, data is flushed only when the window closes, when the player quits and when the server shuts down.</p><p>After <code>drain_timeout_seconds</code> elapses, the remaining dirty entry count is logged and shutdown continues; the server shutdown flow is never blocked indefinitely.</p>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};